import React from 'react';
import { Link } from 'react-router-dom';
import { TruckIcon, ShoppingBagIcon, HomeIcon } from '@heroicons/react/24/outline';

const Orders = () => {
  return (
    <div className="flex min-h-screen bg-gray-100 font-sans">
      <aside className="w-64 bg-blue-900 text-white flex flex-col shadow-xl">
        <div className="p-6 border-b border-blue-800">
          <h1 className="text-2xl font-bold flex items-center gap-2 text-yellow-400">
            <HomeIcon className="w-8 h-8" /> BigMart
          </h1>
        </div>
        <nav className="mt-6">
          <Link to="/orders" className="flex items-center gap-3 px-6 py-4 bg-blue-700 border-r-4 border-yellow-400">
            <TruckIcon className="w-5 h-5 text-yellow-400" />
            <span className="font-bold">Active Orders</span>
          </Link>
          <Link to="/history" className="flex items-center gap-3 px-6 py-4 hover:bg-blue-800 transition-all">
            <ShoppingBagIcon className="w-5 h-5" />
            <span>Order History</span>
          </Link>
        </nav>
      </aside>

      <main className="flex-1 p-8">
        <h2 className="text-3xl font-bold">Active Orders</h2>
        <div className="mt-6 p-10 bg-white rounded-xl shadow border border-gray-200">
          <p className="text-gray-500">දැනට පවතින ඇණවුම් මෙහි පෙන්වනු ඇත...</p>
        </div>
      </main>
    </div>
  );
};

export default Orders;
